Zig 0.11 StringHashMap:
```
pub fn getOrPut(self: *Self, key: []const u8) Error!Entry {
    const hashed_key = try self.hasher.calcString(key);
    const index = self.indexOf(hashed_key);
    if (index) |i| return .{ .key = self.items[i].key, .value = self.items[i].value, .found_existing = true };
    const new_key = try self.allocator.dupe(u8, key);
    const new_index = self.insertUnhashed(hashed_key, new_key);
    self.items[new_index].value = zero;
    return .{ .key = self.items[new_index].key, .value = self.items[new_index].value, .found_existing = false };
}
```
